/* guardian angel has been affected by conflict so is abandoning hero */
/** C ref: minion.c:468 — @param {CPtr<struct monst>} mon */
export function* lose_guardian_angel(mon) {
    let mm = cptr.alloc(4);
    let i;

    if (mon) {
        if (canspotmon(mon)) {
            if (!Deaf()) {
                (yield* pline(__s_s_rebukes_you_saying, (yield* Monnam(mon))));
                ;
                (yield* verbalize(__s_since_you_desire_conflict_have_some_more));
            } else {
                (yield* pline(__s_s_vanishes, (yield* Monnam(mon))));
            }
        }
        (yield* mongone(mon));
    }
    /* create 2 to 4 hostile angels to replace the lost guardian */
    for (i = ((rn2(3) + 2) | 0); i > 0; --i) {
        cptr.stI16(mm, cptr.ldI16(u));
        cptr.stI16o(mm, $nhcoord_y, cptr.ldI16o(u, $you_uy));
        if ((yield* enexto(
            mm,
            cptr.ldI16(mm),
            cptr.ldI16o(mm, $nhcoord_y),
            cptr.add(mons, NHC.PM_ANGEL, $sizeof_permonst)
        )))
            void (yield* mk_roamer(
                cptr.add(mons, NHC.PM_ANGEL, $sizeof_permonst),
                cptr.ld1so(u, $you_ualign),
                cptr.ldI16(mm),
                cptr.ldI16o(mm, $nhcoord_y),
                0
            ));
    }
}

/* just entered the Astral Plane; receive tame guardian angel if worthy */
/** C ref: minion.c:498 */
export function* gain_guardian_angel() {
    let mtmp;
    let otmp;
    let mm = cptr.alloc(4);

    (yield* Hear_again());
    if (Conflict()) {
        if (!Deaf())
            (yield* pline(__s_a_voice_booms));
        else
            (yield* You_feel(__s_a_booming_voice));
        ;
        (yield* verbalize(__s_thy_desire_for_conflict_shall_be));
        /* send in some hostile angels instead */
        (yield* lose_guardian_angel(null));
    } else if (cptr.ldI32o(u, $you_ualign + $align_record) > 8) {
        if (!Deaf())
            (yield* pline(__s_a_voice_whispers));
        else
            (yield* You_feel(__s_a_soft_voice));
        ;
        (yield* verbalize(__s_thou_hast_been_worthy_of_me));
        cptr.stI16(mm, cptr.ldI16(u));
        cptr.stI16o(mm, $nhcoord_y, cptr.ldI16o(u, $you_uy));
        if ((yield* enexto(
            mm,
            cptr.ldI16(mm),
            cptr.ldI16o(mm, $nhcoord_y),
            cptr.add(mons, NHC.PM_ANGEL, $sizeof_permonst)
        )) &&
                (mtmp = (yield* mk_roamer(
                    cptr.add(mons, NHC.PM_ANGEL, $sizeof_permonst),
                    cptr.ld1so(u, $you_ualign),
                    cptr.ldI16(mm),
                    cptr.ldI16o(mm, $nhcoord_y),
                    1
                ))) !== null) {
            cptr.stU64o(
                mtmp,
                $monst_mstrategy,
                cptr.ldU64o(mtmp, $monst_mstrategy) & 18446744071562067967n
            );
            /* guardian angel -- the one case mtame doesn't imply an
             * edog structure, so we don't want to call tamedog().
             * [Note: this predates mon->mextra which allows a monster
             * to have both emin and edog at the same time.]
             */
            /* Too nasty for the game to unexpectedly break petless conduct on
             * the final level of the game. The angel will still appear, but
             * won't be tamed. */
            if (cptr.ldI64o(u, $you_uconduct + $u_conduct_pets)) {
                cptr.st1o(mtmp, $monst_mtame, 10);
                (cptr.stI64o(
                    u,
                    $you_uconduct + $u_conduct_pets,
                    cptr.ldI64o(u, $you_uconduct + $u_conduct_pets) + 1n
                )) -
                        (1n);
            }
            /* for 'hilite_pet'; after making tame, before next message */
            (yield* newsym(cptr.ldI16o(mtmp, $monst_mx), cptr.ldI16o(mtmp, $monst_my)));
            if (!Blind())
                (yield* pline(__s_an_angel_appears_near_you));
            else
                (yield* You_feel(__s_the_presence_of_a_friendly_angel_near));
            /* make him strong enough vs. endgame foes */
            cptr.st1o(mtmp, $monst_m_lev, uchar(((rn2(8) + 15) | 0)));
            cptr.stI32o(
                mtmp,
                $monst_mhp,
                cptr.stI32o(
                    mtmp,
                    $monst_mhpmax,
                    (d((cptr.ld1uo(mtmp, $monst_m_lev)), 10) + 30 + rnd(30)) | 0
                )
            );
            if ((otmp = (yield* select_hwep(mtmp))) === null) {
                otmp = (yield* mksobj(NHC.SILVER_SABER, 0, 0));
                if ((yield* mpickobj(mtmp, otmp)))
                    (yield* panic(__s_merged_weapon));
            }
            (yield* bless(otmp));
            if (cptr.ld1so(otmp, $obj_spe) < 4)
                cptr.st1o(otmp, $obj_spe, cptr.ld1so(otmp, $obj_spe) + rnd(4));
            if ((otmp = (yield* which_armor(mtmp, 8n))) === null ||
                    cptr.ldI16o(otmp, $obj_otyp) != NHC.SHIELD_OF_REFLECTION) {
                void (yield* mongets(mtmp, NHC.AMULET_OF_REFLECTION));
                (yield* m_dowear(mtmp, 1));
            }
        }
    }
}

